#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && (*so_far).keywords.has(Keyword::Flying)) }
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, blocker: ObjectId, attacker: ObjectId) -> bool { let asker = &Asker::new(source, q.controller(source)); !((q.chars(blocker).is(CardType::Creature) && q.chars(blocker).keywords.has(Keyword::Flying)) && !((q.chars(attacker).is(CardType::Creature) && q.chars(attacker).keywords.has(Keyword::Flying)))) }

